window.ATLAS.addDetails("matter.nodes",{"nodes":{
"atomic-structure":{"description":{"zh":"原子中间是一个极小、却装着几乎全部质量的原子核（质子和中子），电子在外面分层分布；核里质子的个数决定它是哪种元素。","en":"An atom is a tiny nucleus of protons and neutrons that carries almost all of its mass, with electrons arranged in layers around it; the number of protons in the nucleus decides which element it is."},"source":"../chemistry/matter/atomic-structure/#step1","lessons":[{"slug":"atomic-structure","step":1,"category":"chemistry","stage":"junior","primary":true}],"aliases":{"zh":["原子是什么","原子核","质子 中子 电子","原子序数","核电荷数","原子里面是空的吗","元素由什么决定"],"en":["what is an atom","atomic nucleus","protons, neutrons and electrons","atomic number","nuclear charge","is an atom mostly empty space","what makes an element that element"]}},
"combustion-triangle":{"description":{"zh":"燃烧需要可燃物、氧气和达到着火点的温度三者同时具备，灭火就是抽掉其中一条；接触面积与氧气供应决定烧得多快。仅为简化的教学三角模型，数值为近似值。","en":"Burning needs fuel, oxygen and a temperature at the ignition point together, and putting out a fire means removing one; contact area and oxygen supply set how fast it burns. A simplified teaching model with approximate numbers."},"source":"../chemistry/reactions/combustion-triangle/#step3","lessons":[{"slug":"combustion-triangle","step":3,"category":"chemistry","stage":"junior","primary":true}],"note":"No chemistry group in the atlas; group left OTHER. The edge uses this page's own conceptId on both sides with a same-page reason.","aliases":{"zh":["燃烧","燃烧是什么反应","着火的条件"],"en":["combustion","burning","what is fire"]}},
"conservation-of-mass":{"description":{"zh":"化学反应只是把原子重新组合，原子的种类和个数都不变，所以密闭体系反应前后总质量相等；敞口反应看起来变轻或变重，是因为有气体跑了出去或从空气里加了进来。","en":"A chemical reaction only regroups atoms without changing their kinds or numbers, so a sealed system weighs the same before and after; when an open reaction seems to get lighter or heavier, a gas has escaped or joined from the air."},"formula":"Σm(reactants) = Σm(products)","source":"../chemistry/reactions/mass-conservation/#step2","lessons":[{"slug":"mass-conservation","step":2,"category":"chemistry","stage":"junior","primary":true}],"aliases":{"zh":["质量守恒定律","反应后为什么变轻了","铁生锈为什么变重","蜡烛烧完质量去哪了","拉瓦锡","物质不灭"],"en":["law of conservation of mass","why does it get lighter after reacting","why does rusting iron get heavier","where does the mass of a burnt candle go","Lavoisier","matter is neither created nor destroyed"]}},
"dissolution-saturation":{"description":{"zh":"一定温度下一定量的水能溶解的某物质有上限（溶解度）；饱和时溶解与结晶仍在进行且速率相等（动态平衡）；降温或蒸发可使多出的溶质结晶。仅为近似数据与一阶速率玩具模型。","en":"At a given temperature a given amount of water can dissolve only so much of a substance (solubility); at saturation dissolving and crystallising continue at equal rates (dynamic equilibrium); cooling or evaporating crystallises the excess. Approximate data and a first-order toy rate model only."},"formula":"w = S / (100 + S)","source":"../chemistry/solutions/dissolution-saturation/#step2","lessons":[{"slug":"dissolution-saturation","step":2,"category":"chemistry","stage":"junior","primary":true}],"note":"No chemistry group in the atlas; group left OTHER. The edge uses this page's own conceptId on both sides with a same-page reason.","aliases":{"zh":["盐为什么能溶于水","溶解","溶于水"],"en":["why does salt dissolve in water","dissolving"]}},
"electron-shells":{"description":{"zh":"电子由里到外一层层填进电子层（本页按 2、8、8 的简化容量），最外层满没满、还差几个，决定原子活不活泼；原子得到或失去电子后带上电荷，就成了离子。","en":"Electrons fill shells from the inside out (2, 8, 8 in this simplified model), and how full the outermost shell is decides how reactive the atom is; an atom that gains or loses electrons becomes charged — an ion."},"formula":"q = Z − nₑ","source":"../chemistry/matter/atomic-structure/#step3","lessons":[{"slug":"atomic-structure","step":3,"category":"chemistry","stage":"junior","primary":true}],"aliases":{"zh":["最外层电子","价电子","电子排布","离子","阳离子 阴离子","为什么钠很活泼","稀有气体为什么稳定","电子壳层"],"en":["outermost electrons","valence electrons","electron configuration","ion","cation and anion","why is sodium so reactive","why are noble gases stable","electron shell"]}},
"equation-balancing":{"description":{"zh":"配平是调整系数，使每种原子在反应式两侧个数相等，并化成最简整数比；依据是反应中原子种类与总数不变。仅适用于本页的简单、理想、完全的反应。","en":"Balancing adjusts coefficients so every element has equal counts on both sides, reduced to the simplest whole-number ratio, because atom kinds and totals do not change in a reaction. Valid for the simple, ideal, complete reactions on this page."},"formula":"2 H₂ + O₂ → 2 H₂O","source":"../chemistry/reactions/equation-balancing/#step0","lessons":[{"slug":"equation-balancing","step":0,"category":"chemistry","stage":"junior","primary":true}],"note":"No chemistry group exists in the atlas; group left OTHER. No existing atlas node fits as an endpoint, so the edge uses this page's own conceptId on both sides with a same-page reason."},
"frozen-bubble":{"description":{"zh":"肥皂泡冷到零下时，冻住的是泡壁薄膜里的水而不是里面的空气：一粒冰核长出枝状冰晶，结冰放出的潜热带动膜里的液体流动，让冰晶看起来像在游动；泡上的彩色来自薄膜干涉，不是冰本身的颜色。","en":"When a soap bubble is chilled below zero, what freezes is the water in its thin wall, not the air inside: a seed crystal grows branching ice, latent heat released by freezing drives liquid flow that makes the crystals seem to swim, and the colours come from thin-film interference rather than from the ice itself."},"source":"../physics/thermal/frozen-bubble/#step0","lessons":[{"slug":"frozen-bubble","step":0,"category":"physics","stage":"junior","primary":true}],"aliases":{"zh":["肥皂泡结冰","冰冻泡泡","泡泡为什么会结出冰花","结晶","潜热","凝固"],"en":["freezing soap bubble","frozen bubble","why do frozen bubbles grow ice patterns","crystallisation","latent heat","freezing / solidification"]}},
"molecules-atoms":{"description":{"zh":"分子是原子连成的团：物理变化只改变分子的位置与间距，化学变化拆开分子、让原子重组成新分子，原子的种类和总数不变。仅适用于分子型物质的教学模型。","en":"A molecule is a cluster of bonded atoms: a physical change only moves molecules, while a chemical change tears them apart and regroups the same atoms into new molecules, keeping atom kinds and totals. A teaching model for molecular substances only."},"formula":"2 H₂O → 2 H₂ + O₂","source":"../chemistry/matter/molecules-atoms/#step2","lessons":[{"slug":"molecules-atoms","step":2,"category":"chemistry","stage":"junior","primary":true}],"note":"No chemistry group exists in the atlas; group left OTHER for the coordinator. No existing atlas node fits as an endpoint, so edges use this page's own conceptId only."},
"particles-states":{"description":{"zh":"固、液、气不是三种东西，是同一群粒子的三种队形：固体排好队原地抖，液体贴身滑动，气体满屋乱飞。加热就是让粒子闹得更凶，闹到挣脱队形就熔化、沸腾。","en":"Solid, liquid and gas are not three things but three formations of the same particles: solids vibrate in formation, liquids slide past each other, gases fly free. Heating makes particles wilder; wild enough to break formation, they melt and boil."},"source":"../chemistry/matter/particles-states/#step1","lessons":[{"slug":"particles-states","step":1,"category":"chemistry","stage":"junior","primary":true}]},
"ph-scale":{"description":{"zh":"pH = −log₁₀[H⁺]：把酸碱程度排成 0–14 的对数刻度，每差 1 个单位 [H⁺] 相差 10 倍；指示剂按各自的 pH 范围变色，酸怎么稀释也只会趋近 7。仅适用于 25 ℃ 的强酸强碱水溶液模型。","en":"pH = −log₁₀[H⁺]: acidity on a 0–14 logarithmic ruler where each unit is a factor of 10 in [H⁺]; indicators change colour within their own pH ranges, and diluting an acid only approaches 7. Valid for strong acids and bases in water at 25 °C."},"formula":"pH = −log₁₀[H⁺]","source":"../chemistry/solutions/ph-scale/#step1","lessons":[{"slug":"ph-scale","step":1,"category":"chemistry","stage":"junior","primary":true}],"note":"No chemistry group in the atlas; group left OTHER. The edge uses this page's own conceptId on both sides with a same-page reason.","aliases":{"zh":["酸碱度","pH","pH 值","酸性 碱性","酸和碱","酸碱","什么是酸 什么是碱"],"en":["pH","acidity","acid or alkaline","how acidic","acids and bases","acid and base"]}},
"buffer-solution":{"description":{"zh":"弱酸和它的共轭碱一起放在溶液里，外来的酸或碱会先被它们接住，pH 只小幅移动；pH 由两者的比值决定，能扛多少则由它们的总浓度决定。","en":"A weak acid together with its conjugate base catches incoming acid or base first, so pH moves only a little; the ratio of the two sets the pH, and their total concentration sets how much they can absorb."},"formula":"pH = pKa + log([A⁻]/[HA])","source":"../chemistry/solutions/buffer-capacity/#step1","lessons":[{"slug":"buffer-capacity","step":1,"category":"chemistry","stage":"senior","primary":true}],"aliases":{"zh":["缓冲液","亨德森–哈塞尔巴尔赫方程","缓冲容量","为什么加酸 pH 几乎不变","共轭酸碱对","血液为什么能保持 pH 稳定"],"en":["buffer","Henderson–Hasselbalch equation","buffer capacity","why does pH barely change when acid is added","conjugate acid–base pair","how does blood keep its pH steady"]}},
"collision-theory":{"description":{"zh":"反应快慢取决于单位时间里有多少次“成功碰撞”——碰得越勤、能量越过门槛的比例越大，反应就越快；提高浓度、升温、磨成粉末、加催化剂，改的都是这两件事之一。","en":"How fast a reaction goes depends on how many successful collisions happen per unit time — more frequent collisions and a larger share clearing the energy threshold make it faster; raising concentration, heating, powdering a solid and adding a catalyst each change one of these two things."},"source":"../chemistry/reactions/reaction-rates/#step0","lessons":[{"slug":"reaction-rates","step":0,"category":"chemistry","stage":"senior","primary":true}],"aliases":{"zh":["反应速率","影响反应速率的因素","有效碰撞","为什么升温反应变快","为什么粉末反应更快","催化剂怎么加快反应","碰撞理论"],"en":["reaction rate","factors that affect reaction rate","effective collision","why does heating speed up a reaction","why does a powder react faster","how does a catalyst speed up a reaction","collision theory"]}},
"dynamic-equilibrium":{"description":{"zh":"可逆反应到了平衡并没有停下，而是正反应和逆反应跑得一样快，所以各物质的量不再变化；加料或改温度会让平衡移动，催化剂只让它更快到达、不改变平衡点。","en":"A reversible reaction at equilibrium has not stopped: the forward and reverse reactions run equally fast, so the amounts stop changing; adding material or changing the temperature shifts the balance, while a catalyst only gets there sooner and does not move it."},"formula":"v(forward) = v(reverse)","source":"../chemistry/reactions/chemical-equilibrium/#step1","lessons":[{"slug":"chemical-equilibrium","step":1,"category":"chemistry","stage":"senior","primary":true}],"aliases":{"zh":["化学平衡","动态平衡","勒夏特列原理","平衡移动","反应到平衡就停了吗","可逆反应","催化剂会改变平衡吗"],"en":["chemical equilibrium","dynamic equilibrium","Le Chatelier's principle","equilibrium shift","does a reaction stop at equilibrium","reversible reaction","does a catalyst change the equilibrium"]}},
"protein-hydrolysis-taste":{"description":{"zh":"随机切断肽键时，游离氨基酸的比例约为切开比例的平方；豆腐 0.24% 游离，腐乳约 6%–25%。还说明了腐乳、酱豆腐、红方、白方、青方的关系。","en":"With random bond cutting the free amino-acid share is about the square of the share of bonds cut; tofu is 0.24% free, fermented tofu about 6–25%. Also explains sufu, red, white and grey fermented tofu."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch1","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch1","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["腐乳为什么好吃","酱豆腐为什么好吃","酱豆腐","豆腐乳","腐乳","红方","白方","青方","南乳","豆腐为什么没味道","蛋白质水解","游离氨基酸","红腐乳为什么是红的","红曲"],"en":["why does fermented tofu taste good","fermented bean curd","sufu","furu","red fermented tofu","protein hydrolysis","free amino acids","why is tofu bland","random chain scission","red yeast rice Monascus"]}},
"soy-sauce-process-timeline":{"description":{"zh":"两三天养曲霉，几个月让盐水里的乳酸菌和酵母接力，最后几十分钟加热；时间轴上的点由后面的模型算出。","en":"Two to three days of mould, months of a bacteria-to-yeast relay in brine, then minutes of heating; the timeline points come from the later models."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch1","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch1","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["酱油是怎么做的","酱油是怎么酿出来的","酱油的原料","酿造酱油的工艺","酱醪","酱油发酵要多久"],"en":["how is soy sauce made","soy sauce brewing process","moromi","how long does soy sauce ferment"]}},
"weak-acid-equilibrium":{"description":{"zh":"弱酸在水里只有一部分解离成 H⁺ 和 A⁻，Ka 越大解离的比例越高；加水稀释反而让解离比例上升，加入 A⁻（共同离子）则把平衡推回去。","en":"A weak acid splits only partly into H⁺ and A⁻ in water, and the larger Ka is, the larger that share; diluting it actually raises the share that dissociates, while adding A⁻ (a common ion) pushes the balance back."},"formula":"Ka = [H⁺][A⁻]/[HA]","source":"../chemistry/solutions/acid-base-equilibrium/#step1","lessons":[{"slug":"acid-base-equilibrium","step":1,"category":"chemistry","stage":"senior","primary":true}],"aliases":{"zh":["弱酸","电离平衡","Ka 是什么","电离常数","同离子效应","为什么醋酸是弱酸","稀释后电离度变大","pKa"],"en":["weak acid","acid dissociation equilibrium","what is Ka","acid dissociation constant","common-ion effect","why is acetic acid a weak acid","dilution raises the degree of dissociation","pKa"]}},
"endo-exo-peptidase":{"description":{"zh":"霉菌两天造出酶，酶在盐卤里切几个月；内切酶造出链头，外切酶才有地方剪，两种一起远快于各自之和。口感为什么变得像奶油。","en":"The mould makes the enzymes in two days; the enzymes work for months. Endopeptidases create chain ends for exopeptidases, so together they free far more than both alone. Why the texture turns creamy."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch2","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch2","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["腐乳怎么做的","腐乳上的毛是什么","毛霉","毛坯","内切酶","外切酶","蛋白酶","腐乳为什么是软的","发酵为什么要放几个月"],"en":["how is fermented tofu made","Actinomucor elegans","Mucor","pehtze","endopeptidase","exopeptidase","protease synergy","why is fermented tofu creamy"]}},
"koji-making-heat":{"description":{"zh":"曲霉长在蒸黄豆和炒小麦上，两三天造出蛋白酶和淀粉酶；生长放热，曲床太厚不翻就超过 40 °C。逻辑斯谛生长加热量平衡的模型。","en":"Koji mould grows on steamed soybeans and roasted wheat and makes proteases and amylases in two to three days; growth releases heat and a thick unturned bed passes 40 °C. Logistic growth with a heat balance."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch2","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch2","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["米曲霉","曲是什么","酱油曲","制曲","翻曲","曲霉"],"en":["what is koji","Aspergillus oryzae","koji mold","koji making","Aspergillus sojae"]}},
"soybean-wheat-ratio":{"description":{"zh":"黄豆给蛋白质，小麦给淀粉和糖；按比例算出的糖决定后面的酵母吃不吃得饱。溜酱油、浓口、中式 80:20 与 70:30 的比较。","en":"Soybeans bring protein, wheat brings starch and sugar; the sugar the ratio provides decides whether the yeast later has enough to eat. Tamari, koikuchi and Chinese 80:20 and 70:30 compared."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch3","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch3","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["酱油为什么加小麦","溜酱油","白酱油","酱油里有小麦吗","无小麦酱油"],"en":["tamari vs soy sauce","does soy sauce contain wheat","koikuchi","shiro soy sauce","wheat in soy sauce"]}},
"umami-synergy":{"description":{"zh":"鲜味来自谷氨酸，核苷酸让它成倍放大；用 Yamaguchi 等效鲜味浓度算腐乳烧肉。","en":"Umami comes from glutamate and is multiplied by nucleotides; Yamaguchi's equivalent umami concentration applied to fermented tofu braised with pork."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch3","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch3","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["鲜味","鲜味是什么","味精","味精是什么","谷氨酸钠","谷氨酸","肌苷酸","鲜味相乘","为什么腐乳烧肉好吃","鲜味受体","等效鲜味浓度"],"en":["umami","what is umami","MSG","monosodium glutamate","glutamate","inosinate IMP","umami synergy","umami receptor T1R1 T1R3","equivalent umami concentration","EUC"]}},
"moromi-microbial-relay":{"description":{"zh":"嗜盐四联球菌先产酸把 pH 拉到 5 以下，鲁氏接合酵母才能在浓盐里接棒产酒精和香气；在模型里，盐超过约 20.6% 或温度太低，接力就失败。","en":"Tetragenococcus halophilus acidifies the mash below pH 5 so that Zygosaccharomyces rouxii can take over in strong brine and make ethanol and aroma; in the model, above about 20.6% salt or in the cold the relay fails."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch4","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch4","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["嗜盐四联球菌","鲁氏接合酵母","酱油里的乳酸菌","酱油发酵的微生物","酱醪的 pH"],"en":["Tetragenococcus halophilus","Zygosaccharomyces rouxii","soy sauce microbes","moromi fermentation","soy sauce yeast"]}},
"salt-water-activity":{"description":{"zh":"Pitzer 模型算盐水的水分活度，对照各致病菌的最低生长值；盐越多越安全，酶也越慢。","en":"Water activity of brine from the Pitzer model against the minimum for each pathogen; more salt is safer but slows the enzymes."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch4","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch4","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["水分活度","为什么盐能防腐","腌制为什么不坏","盐为什么能保存食物","腐乳为什么那么咸","低盐腐乳"],"en":["water activity","why does salt preserve food","salt curing","brine preservation","why is fermented tofu so salty","minimum water activity for bacteria"]}},
"odour-activity-value":{"description":{"zh":"浓度除以阈值才决定闻到什么；腐乳的酯香从哪来。","en":"Concentration divided by threshold decides what you smell; where the fruity esters of fermented tofu come from."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch5","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch5","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["气味活度值","腐乳为什么香","气味阈值","香味是怎么来的","发酵的香味"],"en":["odour activity value","OAV","odor threshold","why does fermented tofu smell good","aroma compounds esters"]}},
"soy-sauce-browning":{"description":{"zh":"氨基酸和糖的美拉德反应生成类黑精；阿伦尼乌斯方程换算加热、室温和冰箱的差别，结论取决于在酱油上还没测准的活化能。开瓶后变深还和氧化有关。","en":"The Maillard reaction between amino acids and sugars makes melanoidins; the Arrhenius equation compares heating, room temperature and the fridge, and the answer hinges on an activation energy not yet measured for soy sauce. Oxidation also darkens an opened bottle."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch5","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch5","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["酱油为什么是黑的","酱油开封后为什么变黑","酱油要不要放冰箱","生抽和老抽的区别","老抽为什么颜色深","酱油的颜色"],"en":["why is soy sauce brown","light vs dark soy sauce","does soy sauce need to be refrigerated","why does soy sauce darken","soy sauce colour"]}},
"century-egg-alkali":{"description":{"zh":"松花蛋不是发酵食品：氢氧化钠从壳外扩散进来，让蛋清凝成胶，碱多了又会化；颜色、松花和马尿谣言。","en":"Century egg is not fermented: sodium hydroxide diffuses in through the shell, gels the white, and liquefies it again if there is too much; the colours, the pine-flower crystals, and the horse-urine myth."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch6","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch6","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["松花蛋为什么是黑的","皮蛋为什么是黑的","松花是什么","皮蛋怎么做的","松花蛋是发酵的吗","皮蛋是马尿泡的吗","皮蛋","松花蛋","皮蛋蛋黄为什么是绿的","碱伤"],"en":["why is century egg black","century egg","pidan","preserved egg","thousand-year egg","is century egg fermented","century egg horse urine","why is century egg yolk green","pine flower pattern century egg"]}},
"soy-sauce-aroma-sources":{"description":{"zh":"酵母带来酒精、HEMF 和 3-甲硫基丙醇，念珠菌把小麦的酚类变成 4-乙基愈创木酚，加热生成呋喃酮。","en":"Yeast brings ethanol, HEMF and methionol, Candida turns wheat phenolics into 4-ethylguaiacol, and heating forms furanones."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch6","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch6","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["酱油为什么香","酱香","HEMF","4-乙基愈创木酚","酱油加热"],"en":["soy sauce aroma","HEMF","4-ethylguaiacol","soy sauce pasteurization"]}},
"amino-acid-nitrogen-label":{"description":{"zh":"甲醛滴定数的是游离氨基，加进去的谷氨酸钠和铵盐也会被数进去；GB/T 18186 的特级到三级，2025 版的铵盐上限 28%，以及日本 JAS 按总氮分级。","en":"Formol titration counts free amino groups, so added sodium glutamate and ammonium count too; the GB/T 18186 grades, the 28% ammonium cap in the 2025 edition, and Japan's JAS grades by total nitrogen."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch7","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch7","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["氨基酸态氮是什么","酱油特级一级区别","酱油等级","酱油有味精吗","酱油标签怎么看","甲醛滴定","GB/T 18186"],"en":["amino acid nitrogen soy sauce","soy sauce grade","formol titration","soy sauce label China","JAS soy sauce grades"]}},
"fermented-food-family":{"description":{"zh":"腐乳和松花蛋只有一半相同；酱油、奶酪、火腿、鱼露、纳豆、臭豆腐：谁来切、切什么、什么挡住坏菌。","en":"Fermented tofu and century egg are only half alike; soy sauce, cheese, ham, fish sauce, natto and stinky tofu: who cuts, what is cut, and what keeps spoilage out."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch7","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch7","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["发酵食品原理","火腿为什么鲜","鱼露","纳豆","奶酪为什么鲜","松花蛋和腐乳一样吗"],"en":["how fermentation makes flavor","dry-cured ham flavor","fish sauce","natto","cheese ripening","fermented foods compared"]}},
"brewed-vs-hydrolysed-soy-sauce":{"description":{"zh":"高盐稀态走完整个接力；低盐固态更快；酸水解几天切完蛋白质、会生成 3-MCPD，在中国现行规定下不能叫酱油（GB 2717-2018 和市场监管总局 2021 年公告；3-MCPD 限量见 GB 2762-2025）。","en":"High-salt liquid brewing runs the whole relay; low-salt solid-state is faster; acid hydrolysis breaks protein in days and forms 3-MCPD, and under current Chinese rules may not be called soy sauce."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch8","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch8","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["酿造酱油和配制酱油","配制酱油","高盐稀态","低盐固态","酸水解植物蛋白","3-氯-1,2-丙二醇","氯丙醇"],"en":["brewed vs chemical soy sauce","hydrolyzed vegetable protein soy sauce","naturally brewed soy sauce","3-MCPD soy sauce","low-salt solid-state fermentation"]}},
"why-stinky-smells":{"description":{"zh":"冲淡以后剩下的气味组合不同；臭的分子还没有定论；对气味的喜欢是学来的。","en":"Dilution leaves different combinations of odours; the stinky molecules are not settled; liking a smell is learned."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch8","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch8","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["臭豆腐为什么臭","臭豆腐为什么闻着臭吃着香","臭豆腐","为什么有人喜欢吃臭的","闻着臭吃着香"],"en":["why does stinky tofu smell","stinky tofu","smells bad tastes good","acquired taste","aroma extract dilution analysis"]}},
"fermented-tofu-safety":{"description":{"zh":"腐乳的钠含量、青方的生物胺、皮蛋铅限量在 GB 2762 里的变化；只讲机制和标准。","en":"Sodium in fermented tofu, biogenic amines in grey sufu, and how the lead limit for century eggs changed in GB 2762; mechanisms and standards only."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch9","lessons":[{"slug":"why-fermented-tofu-tastes-good","step":null,"anchor":"ch9","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["皮蛋有铅吗","松花蛋含铅吗","无铅皮蛋","腐乳钠含量","腐乳太咸","生物胺","组胺","酪胺","GB 2762 铅"],"en":["does century egg contain lead","lead in preserved eggs","sodium in fermented tofu","biogenic amines","histamine tyramine fermented food","GB 2762 lead limit"]}},
"soy-sauce-sodium":{"description":{"zh":"浓盐水是酿造条件的一部分；日本几种酱油每 100 克含钠约 5.1–6.3 克，淡口比浓口更咸。只讲含量和机制。","en":"Strong brine is part of the brewing; about 5.1–6.3 g sodium per 100 g in Japanese styles, and usukuchi is saltier than koikuchi. Content and mechanism only."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch9","lessons":[{"slug":"how-soy-sauce-gets-its-flavor","step":null,"anchor":"ch9","category":"food","stage":"senior","primary":true}],"aliases":{"zh":["酱油为什么那么咸","酱油含钠量","淡口酱油","减盐酱油","一勺酱油多少盐"],"en":["why is soy sauce so salty","sodium in soy sauce","usukuchi","low sodium soy sauce"]}}
}});
